class SagaOrchestrator:
    def __init__(self):
        self.steps = []
    def add_step(self, execute_fn, compensate_fn):
        self.steps.append((execute_fn, compensate_fn))
    async def run(self):
        executed = []
        for exe, comp in self.steps:
            try:
                await exe()
                executed.append(comp)
            except Exception:
                for c in reversed(executed): await c()
                raise
